-- Local synthetic fixture only. Never run on hosted data; no provider request is made.
begin;
create temporary table gs(owner_id uuid,outsider uuid,w uuid,s uuid,c uuid,run uuid,profile uuid,test_run uuid,coordinator uuid,content uuid,quality uuid,claim1 uuid,claim2 uuid,claim3 uuid);
insert into gs values(gen_random_uuid(),gen_random_uuid(),null,null,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select owner_id from gs union all select outsider from gs;
create function pg_temp.gsexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;else raise exception 'Unexpected: %',sqlerrm;end if;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on gs to authenticated,anon,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);
update gs set w=(select id from public.bz_create_workspace('Stage accounting fixture'));
update gs set s=(select id from public.bz_register_site(w,'Draft pilot','external','business','https://stage-fixture.com/',null,'active',true));
select public.bz_save_site_agent_preferences(w,s,'{"brandVoice":"practical","audience":"small business owners","guidance":"Draft only"}',0) from gs;
select public.bz_mutate_knowledge(w,s,gen_random_uuid(),'save','{"title":"Approved facts","filename":"facts.md","sourceText":"Bizoveya prepares private reviewable drafts.","facts":[{"id":"f1","text":"Bizoveya prepares private reviewable drafts."}]}',0) from gs;
select public.bz_mutate_knowledge(w,s,(select id from public.bizoveya_knowledge_sources where site_id=s),'approve',null,1) from gs;
select public.bz_save_campaign(w,s,c,'{"title":"Pilot","brief":"Prepare three draft formats","blog":"","pinterest":"","linkedin":""}',0) from gs;
reset role;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile,'stage-fixture',1,1 from gs;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile,1,'{"name":"Fixture Gemini","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic stage fixture' from gs;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile,1,'platform-gemini',1 from gs;
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,input_tokens,output_tokens,reason,finished_at) select test_run,profile,1,'platform-gemini',1,gen_random_uuid(),'passed','response_matched',20,7,'Synthetic connectivity evidence',clock_timestamp() from gs;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile,1,1,jsonb_build_object('enabled',true,'inputRateMicros',0,'outputRateMicros',0,'requestFeeMicros',0,'dailyLimitMicros',10000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/fictional-pricing','reviewed',true),'Synthetic reviewed prices' from gs;
update bizoveya_private.agent_versions set document=jsonb_set(document,'{modelTier}','"economical"') where version=1 and agent_id in(select id from bizoveya_private.agent_definitions where kind in('coordinator','content','quality'));
update bizoveya_private.agent_definitions set preview_version=1 where kind in('coordinator','content','quality');
insert into bizoveya_private.agent_checks(agent_id,version) select id,1 from bizoveya_private.agent_definitions where kind in('coordinator','content','quality') on conflict do nothing;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select a.id,1,g.profile,1,1,g.test_run,1,true,'Synthetic generation binding' from bizoveya_private.agent_definitions a cross join gs g where a.kind in('coordinator','content','quality');
create temporary table rt as select jsonb_build_object('enabled',true,'agents',(select jsonb_agg(jsonb_build_object('kind',kind,'agentId',id,'agentVersion',1) order by kind) from bizoveya_private.agent_definitions)) as document from gs;
grant all on rt to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);
-- Legacy prepared run remains readable, but configuring a team invalidates it for new work.
select public.bz_prepare_campaign_generation(w,s,c,1,run) from gs;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',rt.document,'expectedVersion',0,'reason','Enable reviewed site team only.','reviewed',true)) from gs,rt;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',rt.document,'expectedVersion',0,'reason','Enable reviewed site team only.','reviewed',true)) from gs,rt;
select pg_temp.gsexpect(format('select public.bz_save_site_agent_roster(%L,%L,%L::jsonb)',w,s,jsonb_build_object('document',rt.document,'expectedVersion',0,'reason','Different stale reason','reviewed',true)),'bz_conflict') from gs,rt;
select pg_temp.gsexpect(format('select public.bz_save_site_agent_roster(%L,%L,%L::jsonb)',w,s,jsonb_build_object('document',rt.document,'expectedVersion',1,'reason','Unreviewed','reviewed',false)),'bz_invalid_site_roster') from gs,rt;
reset role;
select bizoveya_private.set_platform_admin(owner_id,true,'fixture','Synthetic roster operator') from gs;
set local role authenticated;select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select pg_temp.gsexpect(format('select public.bz_admin_authorize_generation(%L,%L,%L,true)',run,claim1,'Old roster-free snapshot'),'bz_site_roster_changed') from gs;
reset role;
-- A second globally qualified Content role must not make this selected site team ambiguous.
insert into bizoveya_private.agent_definitions(id,slug,kind,latest_version,preview_version,revision) select content,'roster-unselected-content','content',1,1,1 from gs;
insert into bizoveya_private.agent_versions(agent_id,version,document,reason) select g.content,1,(select v.document from bizoveya_private.agent_versions v join bizoveya_private.agent_definitions a on a.id=v.agent_id where a.kind='content' and a.id<>g.content limit 1),'Synthetic unselected role' from gs g;
insert into bizoveya_private.agent_checks(agent_id,version) select content,1 from gs;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select content,1,profile,1,1,test_run,1,true,'Synthetic unselected binding' from gs;
set local role authenticated;
do $$declare r jsonb;begin select public.bz_agency_onboarding(w,s) into r from gs;if r#>>'{current,roles,1,qualifiedCount}'<>'1' or r#>>'{current,siteTeam,version}'<>'1' then raise exception 'Assessment ignored selected team';end if;end;$$;
create temporary table rr(id uuid,stage uuid,claim uuid);insert into rr values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid());grant all on rr to authenticated,service_role;
select public.bz_prepare_campaign_generation(w,s,c,1,rr.id) from gs,rr;
select public.bz_admin_authorize_generation(rr.id,rr.claim,'Reviewed selected team run',true) from rr;
reset role;set local role service_role;
select public.bz_claim_campaign_generation_stage(rr.id,rr.stage,'coordinator',rr.claim,owner_id) from rr,gs;
reset role;set local role authenticated;
-- Pause between reservation and provider-start: recording must refuse, guarded cancellation still settles zero.
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',jsonb_set(rt.document,'{enabled}','false'),'expectedVersion',1,'reason','Pause new site work.','reviewed',true)) from gs,rt;
select pg_temp.gsexpect(format('select public.bz_prepare_campaign_generation(%L,%L,%L,1,%L)',w,s,c,gen_random_uuid()),'bz_site_roster_paused') from gs;
reset role;set local role service_role;
select pg_temp.gsexpect(format('select public.bz_record_generation_request(%L,%L,%L::jsonb)',stage,claim,'{"runtimeVersion":"draft-runtime-v1-ai7.0.127","instructions":"Private","prompt":"Approved facts"}'),'bz_site_roster_paused') from rr;
select public.bz_cancel_unstarted_generation_stage(stage,claim) from rr;
select pg_temp.gsexpect(format('select public.bz_begin_campaign_generation_stage(%L,%L,%L,%L,%L)',run,gen_random_uuid(),'coordinator',claim1,owner_id),'bz_site_roster_paused') from gs;
select pg_temp.gsexpect(format('select bizoveya_private.begin_generation_before_roster(%L,%L,%L,%L,%L)',run,gen_random_uuid(),'coordinator',claim1,owner_id),'permission denied') from gs;
reset role;
do $$begin if (select provider_started_at from bizoveya_private.generation_stage_runs where id=(select stage from rr)) is not null or (select charged_micros from bizoveya_private.generation_stage_runs where id=(select stage from rr))<>0 then raise exception 'Pause failed zero-cost preflight';end if;end;$$;
-- Expired qualification cannot prevent pause, but cannot re-enable the saved team.
update bizoveya_private.model_test_runs set finished_at=clock_timestamp()-interval '25 hours' where id=(select test_run from gs);
set local role authenticated;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',jsonb_set(rt.document,'{enabled}','false'),'expectedVersion',2,'reason','Retain pause with expired evidence.','reviewed',true)) from gs,rt;
select pg_temp.gsexpect(format('select public.bz_save_site_agent_roster(%L,%L,%L::jsonb)',w,s,jsonb_build_object('document',rt.document,'expectedVersion',3,'reason','Cannot enable expired tests.','reviewed',true)),'bz_site_roster_not_ready') from gs,rt;
reset role;update bizoveya_private.model_test_runs set finished_at=clock_timestamp() where id=(select test_run from gs);
set local role authenticated;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',rt.document,'expectedVersion',3,'reason','Re-enable reviewed qualified team.','reviewed',true)) from gs,rt;
create temporary table started_run(id uuid,stage uuid,claim uuid);insert into started_run values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid());grant all on started_run to authenticated,service_role;
select public.bz_prepare_campaign_generation(w,s,c,1,started_run.id) from gs,started_run;
select public.bz_admin_authorize_generation(id,claim,'Synthetic already-started checkpoint',true) from started_run;
reset role;set local role service_role;
select public.bz_claim_campaign_generation_stage(id,stage,'coordinator',claim,owner_id) from started_run,gs;
-- Simulated start marker only; no provider request is made by this fixture.
select public.bz_record_generation_request(stage,claim,'{"runtimeVersion":"draft-runtime-v1-ai7.0.127","instructions":"Private","prompt":"Approved facts"}') from started_run;
reset role;set local role authenticated;
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',jsonb_set(rt.document,'{enabled}','false'),'expectedVersion',4,'reason','Pause after simulated start.','reviewed',true)) from gs,rt;
reset role;set local role service_role;
select public.bz_finish_campaign_generation_stage(stage,claim,null,'synthetic_provider_failure',0,0) from started_run;
reset role;
do $$begin if (select spending_state from bizoveya_private.generation_stage_runs where id=(select stage from started_run))<>'settled' or (select provider_started_at from bizoveya_private.generation_stage_runs where id=(select stage from started_run)) is null then raise exception 'Pause prevented started-stage settlement';end if;end;$$;
-- Revision quota cannot mutate the current roster/history on rejection.
insert into bizoveya_private.site_agent_roster_revisions(site_id,version,document,reason,actor_id) select site_id,n,document,'Synthetic quota fixture',actor_id from bizoveya_private.site_agent_rosters cross join generate_series(6,50) n;
update bizoveya_private.site_agent_rosters set version=50;
set local role authenticated;
select pg_temp.gsexpect(format('select public.bz_save_site_agent_roster(%L,%L,%L::jsonb)',w,s,jsonb_build_object('document',rt.document,'expectedVersion',50,'reason','Quota must reject new roster','reviewed',true)),'bz_site_roster_limit') from gs,rt;
reset role;update public.bizoveya_memberships set role='viewer' where user_id=(select owner_id from gs);
set local role authenticated;
select public.bz_site_agent_roster(w,s) from gs;
select pg_temp.gsexpect(format('select public.bz_save_site_agent_roster(%L,%L,%L::jsonb)',w,s,jsonb_build_object('document',rt.document,'expectedVersion',50,'reason','Viewer cannot enable','reviewed',true)),'bz_forbidden') from gs,rt;
select pg_temp.gsexpect('select * from bizoveya_private.site_agent_rosters','permission denied');
select set_config('request.jwt.claim.sub',(select outsider::text from gs),true);
select pg_temp.gsexpect(format('select public.bz_site_agent_roster(%L,%L)',w,s),'bz_forbidden') from gs;
reset role;
select pg_temp.gsexpect('update bizoveya_private.site_agent_roster_revisions set reason=''Forged''','bz_immutable_onboarding_review');
delete from public.bizoveya_sites where id=(select s from gs);
do $$begin if exists(select 1 from bizoveya_private.site_agent_rosters where site_id=(select s from gs)) or exists(select 1 from bizoveya_private.site_agent_roster_revisions where site_id=(select s from gs)) then raise exception 'Roster site cascade failed';end if;end;$$;
rollback;
